mapper.select:
SELECT * FROM meeting_room
WHERE deleted = 0

    AND (name LIKE CONCAT('%', #{query.keyword}, '%')
         OR location LIKE CONCAT('%', #{query.keyword}, '%'))


    AND name LIKE CONCAT('%', #{query.name}, '%')


    AND status = #{query.status}


    AND location LIKE CONCAT('%', #{query.location}, '%')


    AND equipment LIKE CONCAT('%', #{query.equipment}, '%')


    AND capacity >= #{query.minCapacity}


    AND bookable_start >= #{query.bookableStart}


    AND bookable_end <= #{query.bookableEnd}


    AND need_approval = #{query.needApproval}


    AND create_time >= #{query.createTimeStart}


    AND create_time <= #{query.createTimeEnd}

ORDER BY create_time DESC
